SELECT a.CSNAME AS `股票名称`, a.COMB_SYMBOL AS `股票代码`, s.SECTOR_CNAME AS `业务板块`, ROUND(s.F007N / 100, 3) AS `收入(亿美元)` FROM AMERICAN_STOCK_MAIN a JOIN VIEW_COM3103_CUM c ON a.FIU_ID = c.FIU_ID JOIN VIEW_COM3105 s ON c.FIU_ID = s.FIU_ID AND c.F001D = s.F001D WHERE a.CSNAME LIKE '%苹果%' AND c.F056N = 2025 AND c.F003V = 'FY' AND s.F007N IS NOT NULL AND s.SECTOR_CNAME IS NOT NULL ORDER BY s.F007N DESC LIMIT 1;
